from fractions import Fraction
a = [[Fraction(1), Fraction(1), Fraction(1), Fraction(6)],
     [Fraction(2), Fraction(1), Fraction(3), Fraction(13)],
     [Fraction(1), Fraction(4), Fraction(1), Fraction(12)]]
n = 3
for k in range(n - 1):
    for i in range(k + 1, n):
        m = a[i][k] / a[k][k]
        for j in range(k, n + 1):
            a[i][j] -= m * a[k][j]
x = [Fraction(0)] * n
for i in range(n - 1, -1, -1):
    s = a[i][n]
    for j in range(i + 1, n):
        s -= a[i][j] * x[j]
    x[i] = s / a[i][i]
for v in x:
    print(v)
